    },
    win: function() {
      window.FactorySound._play(523, 0.09, "triangle", 0.09);
      setTimeout(function() { window.FactorySound._play(659, 0.09, "triangle", 0.09); }, 85);
      setTimeout(function() { window.FactorySound._play(784, 0.16, "triangle", 0.1); }, 170);
    },
    error: function() { window.FactorySound._play(190, 0.16, "sawtooth", 0.06); },
    toggle: function() {
      window.FactorySound.muted = !window.FactorySound.muted;
      localStorage.setItem("sf_muted", window.FactorySound.muted ? "1" : "0");
      window.FactoryUI.toast(window.FactorySound.muted ? "Sound Muted" : "Arcade Sound ON", "info");
    }
  };

  window.FactoryPro = {
    claimDailyBonus: async function() {
      const today = new Date().toISOString().slice(0, 10);
      if (localStorage.getItem("sf_dbonus_" + (window.SF_APP_SLUG || "app")) === today) {
        window.FactoryUI.toast("Today's +50 Pts bonus already claimed!", "warn");
        return false;
      }
      localStorage.setItem("sf_dbonus_" + (window.SF_APP_SLUG || "app"), today);
      if (window.FactoryDB) await window.FactoryDB.recordTx("bonus", 50, "Daily Streak Bonus " + today);
      window.FactorySound.win();
      window.FactoryUI.confetti();
      window.FactoryUI.toast("+50 Daily Bonus Points Added!", "success");
      if (typeof window.onAppReady === "function") { try { await window.onAppReady(); } catch (e) {} }
      return true;
    },
    scoreToken: function(pts) {
      const u = window.FactoryDB ? window.FactoryDB.getUserSync() : null;
      const raw = (u ? u.phone : "0") + ":" + String(pts || 0) + ":SF";
      let h = 0;
      for (let i = 0; i < raw.length; i++) { h = ((h << 5) - h) + raw.charCodeAt(i); h |= 0; }
      return "V1-" + Math.abs(h).toString(36).toUpperCase();
    },
    showProModal: function(planTitle, priceText) {
      window.FactorySound.tap();
      const body = '<div class="sf-hero-card" style="text-align:center;">' +
        '<span class="sf-badge-live">PRO UPGRADE</span>' +
        '<h3 style="margin:8px 0 4px 0;color:#fff;">' + (planTitle || "Pro Pass") + '</h3>' +
        '<div style="font-size:24px;font-weight:800;color:#fde047;margin:6px 0;">' + (priceText || "Rs. 149 / mo") + '</div>' +
        '<p style="font-size:12px;color:#e2e8f0;margin:0;">Ad-Free Experience, Unlimited Cloud Backup, Priority Sync &amp; Pro PDF Exports.</p></div>' +
        '<button type="button" onclick="FactoryPro.activateTrial()" style="width:100%;margin-top:10px;background:#10b981 !important;">Activate Free Trial</button>';
      window.FactoryNav.openDetail(planTitle || "Pro Membership", body);
    },
    activateTrial: function() {
      if (window.FactorySound) window.FactorySound.win();
      window.FactoryUI.confetti();
      window.FactoryUI.toast("Pro Trial Request Logged!", "success");
    }
  };

  window.FactoryGame = {
    _raf: null,
    isUnlocked: function(vId, freeByDefault) {
      if (freeByDefault) return true;
      try {
        const list = JSON.parse(localStorage.getItem("sf_unlock_" + (window.SF_APP_SLUG || "app")) || "[]");
        return list.indexOf(vId) !== -1;
      } catch (e) { return false; }
    },
    unlockVehicle: async function(vId, cost, label) {
      const u = window.FactoryDB ? window.FactoryDB.getUserSync() : null;
      const pts = u ? (u.points || 0) : 0;
      if (pts < cost) {
        if (window.FactorySound) window.FactorySound.error();
        window.FactoryUI.toast("Need " + cost + " Coins! You have " + pts + " Coins.", "warn");
        return false;
      }
      try {
        const key = "sf_unlock_" + (window.SF_APP_SLUG || "app");
        const list = JSON.parse(localStorage.getItem(key) || "[]");
        if (list.indexOf(vId) === -1) list.push(vId);
        localStorage.setItem(key, JSON.stringify(list));
      } catch (e) {}
      if (window.FactoryDB) await window.FactoryDB.recordTx("unlock", -cost, "Unlocked " + label);
      if (window.FactorySound) window.FactorySound.win();
      window.FactoryUI.confetti();
      window.FactoryUI.toast(label + " Unlocked!", "success");
      if (typeof window.onAppReady === "function") { try { await window.onAppReady(); } catch (e) {} }
      return true;
    },
    exitRace: function() {
      if (window.FactoryGame._raf) { cancelAnimationFrame(window.FactoryGame._raf); window.FactoryGame._raf = null; }
      const ov = document.getElementById("sf-game-overlay");
      if (ov) ov.remove();
      try { if (document.fullscreenElement && document.exitFullscreen) document.exitFullscreen(); } catch (e) {}
      try { if (screen.orientation && screen.orientation.unlock) screen.orientation.unlock(); } catch (e) {}
    },
    startVillageRace: function(vehicleName, accentColor) {
      window.FactoryGame.exitRace();
      const ov = document.createElement("div");
      ov.id = "sf-game-overlay";
      ov.style.cssText = "position:fixed;inset:0;z-index:99990;background:#090d1a;display:flex;flex-direction:column;justify-content:space-between;padding:8px;";
      ov.innerHTML =
        '<div style="display:flex;justify-content:space-between;align-items:center;padding:4px 8px;background:rgba(15,23,42,0.9);border-radius:12px;border:1px solid #38bdf8;">' +
          '<div style="color:#fff;font-weight:800;font-size:13px;">' + (vehicleName || "Turbo Racer") + '</div>' +
          '<div id="fg-hud" style="color:#fde047;font-weight:800;font-size:13px;">Score: 0 | Coins: 0</div>' +
          '<button type="button" onclick="FactoryGame.exitRace()" style="min-height:30px;padding:4px 12px;background:#dc2626 !important;font-size:12px;">Exit</button>' +
        '</div>' +
        '<canvas id="fg-canvas" style="width:100%;flex:1;min-height:240px;border-radius:14px;margin:6px 0;background:#14532d;display:block;"></canvas>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;">' +
          '<button id="fg-left" type="button" style="min-height:48px;background:#1e293b !important;border:1px solid #38bdf8;font-size:16px;font-weight:800;">&larr; LEFT</button>' +
          '<button id="fg-boost" type="button" style="min-height:48px;background:linear-gradient(135deg,#f59e0b,#ef4444) !important;font-size:14px;font-weight:800;">NITRO</button>' +
          '<button id="fg-right" type="button" style="min-height:48px;background:#1e293b !important;border:1px solid #38bdf8;font-size:16px;font-weight:800;">RIGHT &rarr;</button>' +
        '</div>';
      document.body.appendChild(ov);
      try { if (ov.requestFullscreen) ov.requestFullscreen().catch(function(){}); } catch (e) {}
      try { if (screen.orientation && screen.orientation.lock) screen.orientation.lock("landscape").catch(function(){}); } catch (e) {}

      const cvs = document.getElementById("fg-canvas");
      const ctx = cvs.getContext("2d");
      cvs.width = cvs.clientWidth || 360;
      cvs.height = cvs.clientHeight || 420;
      let lane = 1, score = 0, coins = 0, speed = 4.2, roadY = 0, alive = true;
      const objs = [];
      const vLow = (vehicleName || "").toLowerCase();
      const vEmoji = vLow.includes("horse") ? "H" : (vLow.includes("bike") ? "B" : (vLow.includes("scooter") ? "S" : "C"));

      function moveLane(dir) {
        lane = Math.max(0, Math.min(2, lane + dir));
        if (window.FactorySound) window.FactorySound.tap();
      }
      document.getElementById("fg-left").onclick = function() { moveLane(-1); };
      document.getElementById("fg-right").onclick = function() { moveLane(1); };
      document.getElementById("fg-boost").onclick = function() { speed = Math.min(9.5, speed + 1.4); if (window.FactorySound) window.FactorySound.coin(); };

      let frame = 0;
      function loop() {
        if (!alive || !document.getElementById("fg-canvas")) return;
        const W = cvs.width, H = cvs.height;
        const roadL = W * 0.2, roadW = W * 0.6, laneW = roadW / 3;
        ctx.fillStyle = "#166534";
        ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = "#334155";
        ctx.fillRect(roadL, 0, roadW, H);

        roadY = (roadY + speed * 2) % 48;
        for (let y = -48; y < H + 48; y += 48) {
          ctx.fillStyle = "#fde047";
          ctx.fillRect(roadL + laneW - 2, y + roadY, 4, 24);
          ctx.fillRect(roadL + laneW * 2 - 2, y + roadY, 4, 24);
          ctx.fillStyle = "#15803d";
          ctx.beginPath(); ctx.arc(roadL * 0.45, y + roadY + 12, 14, 0, 6.28); ctx.fill();
          ctx.fillStyle = "#92400e";
          ctx.fillRect(W - roadL * 0.72, y + roadY + 4, 22, 18);
        }

        frame++;
        if (frame % 26 === 0) {
          objs.push({ lane: Math.floor(Math.random() * 3), y: -24, type: Math.random() < 0.62 ? "coin" : "rock" });
        }
        const px = roadL + lane * laneW + laneW / 2;
        const py = H - 56;
        ctx.fillStyle = accentColor || "#ef4444";
        ctx.fillRect(px - 18, py - 24, 36, 48);
        ctx.fillStyle = "#ffffff";
        ctx.font = "bold 16px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText(vEmoji, px, py + 6);

        for (let i = objs.length - 1; i >= 0; i--) {
          const o = objs[i];
          o.y += speed;
          const ox = roadL + o.lane * laneW + laneW / 2;
          if (o.type === "coin") {
            ctx.fillStyle = "#facc15";
            ctx.beginPath(); ctx.arc(ox, o.y, 12, 0, 6.28); ctx.fill();
          } else {
            ctx.fillStyle = "#dc2626";
            ctx.fillRect(ox - 16, o.y - 12, 32, 24);
          }
          if (Math.abs(o.y - py) < 28 && o.lane === lane) {
            if (o.type === "coin") {
              coins += 10; score += 25; objs.splice(i, 1);
              if (window.FactorySound) window.FactorySound.coin();
            } else {
              alive = false;
              if (window.FactorySound) window.FactorySound.error();
              const finalScore = score + Math.floor(frame / 4);
              const tok = window.FactoryPro ? window.FactoryPro.scoreToken(finalScore) : "V1";
              if (window.FactoryDB) {
                window.FactoryDB.saveItem("race", (vehicleName || "Race") + " (" + finalScore + ")", { score: finalScore, coins: coins, token: tok });
                window.FactoryDB.recordTx("xp", coins, "Race Coins (" + vehicleName + ")");
              }
              window.FactoryUI.toast("Race Over! Score: " + finalScore + " | +" + coins + " Coins", "success");
              setTimeout(function() { window.FactoryGame.exitRace(); if (typeof window.onAppReady === "function") window.onAppReady(); }, 900);
              return;
            }
          } else if (o.y > H + 30) {
            objs.splice(i, 1);
            score += 5;
          }
        }
        const hud = document.getElementById("fg-hud");
        if (hud) hud.textContent = "Score: " + (score + Math.floor(frame / 4)) + " | +" + coins + " Coins";
        window.FactoryGame._raf = requestAnimationFrame(loop);
      }
      window.FactoryGame._raf = requestAnimationFrame(loop);
    }
  };

  window.FactoryEngine = {
    rtSocket: null,
    copyUserId: function() {
      const u = window.FactoryDB ? window.FactoryDB.getUserSync() : null;
      const uid = "SF" + String((u && u.phone) ? u.phone : "100001").slice(-6);
      try { navigator.clipboard.writeText(uid); } catch (e) {}
      window.FactoryUI.toast("Copied ID: " + uid, "success");
    },
    openReferShare: function() {
      const u = window.FactoryDB ? window.FactoryDB.getUserSync() : null;
      const code = "SF" + String((u && u.phone) ? u.phone : "100001").slice(-6);
      const msg = "Join me on " + document.title + "! Use my referral code " + code + " to get started.";
      const waUrl = "https://wa.me/?text=" + encodeURIComponent(msg);
      const body = '<div class="sf-hero-card" style="text-align:center;">' +
        '<div style="font-size:12px;color:#cbd5e1;">YOUR UNIQUE REFERRAL CODE</div>' +
        '<div style="font-size:24px;font-weight:800;color:#34d399;letter-spacing:2px;margin:8px 0;">' + code + '</div>' +
        '<p style="font-size:12px;color:#e2e8f0;margin:0;">Share with friends to earn +25 bonus points on every invite.</p></div>' +
        '<button type="button" onclick="FactoryEngine.triggerShare()" style="width:100%;margin-bottom:10px;background:#10b981 !important;">Share via App / Copy</button>' +
        '<a href="' + waUrl + '" target="_blank" style="display:block;text-align:center;padding:12px;border-radius:12px;background:#16a34a;color:#fff;font-weight:700;text-decoration:none;">Share on WhatsApp</a>';
      window.FactoryNav.openDetail("Refer & Share", body);
    },
    triggerShare: async function(code) {
      const u = window.FactoryDB ? window.FactoryDB.getUserSync() : null;
      const finalCode = code || ("SF" + String((u && u.phone) ? u.phone : "100001").slice(-6));
      const msg = "Join me on " + document.title + "! Referral Code: " + finalCode;
      if (navigator.share) {
        try { await navigator.share({ title: document.title, text: msg }); } catch (e) {}
      } else {
        try { navigator.clipboard.writeText(msg); } catch (e) {}
      }
      window.FactoryUI.toast("Invite link ready & +25 Pts logged!", "success");
      window.FactoryUI.confetti();
    },
    openTutorial: function() {
      const custom = window.APP_TUTORIAL_HTML || ('<div class="sf-card"><h3 style="margin:0 0 8px 0;color:#38bdf8;">How to Use ' + document.title + '</h3>' +
        '<p style="color:#cbd5e1;font-size:13px;line-height:1.5;">1. Use bottom floating tabs to switch Home, Actions, Records & Profile.<br>' +
        '2. Tap any card to open its full detail view and use Back to return.<br>' +
        '3. Tap the + button anytime for quick cloud actions synced with Supabase.</p></div>');
      window.FactoryNav.openDetail("App Guide & Tutorial", custom);
    },
    openNotifications: function() {
      const u = window.FactoryDB ? window.FactoryDB.getUserSync() : null;
      const html = '<div class="sf-list-row"><div><strong style="color:#fff;">Cloud Sync Active</strong><div style="font-size:12px;color:#94a3b8;">Connected to live Supabase Realtime</div></div><span class="sf-badge-live">LIVE</span></div>' +
        '<div class="sf-list-row"><div><strong style="color:#fff;">Welcome ' + (u ? u.full_name : "User") + '</strong><div style="font-size:12px;color:#94a3b8;">Your session & points are synced.</div></div><span class="sf-badge-live">OK</span></div>';
      window.FactoryNav.openDetail("Notifications", html);
    },
    startRealtime: function(onDataChange) {
      if (window.FactoryEngine.rtSocket) return;
      try {
        const ws = new WebSocket("wss://saexbzapfzfkzqkunsom.supabase.co/realtime/v1/websocket?apikey=sb_publishable_3YZ2OA5MiOoVoLqFCXcsxw_JIjNlEjY&vsn=1.0.0");
        window.FactoryEngine.rtSocket = ws;
        ws.onopen = function() {
          ws.send(JSON.stringify({ topic: "realtime:public:factory_app_items", event: "phx_join", payload: {}, ref: "1" }));
        };
        ws.onmessage = function(ev) {
          try {
            const msg = JSON.parse(ev.data);
            if (msg && (msg.event === "INSERT" || msg.event === "UPDATE" || msg.event === "DELETE" || msg.event === "postgres_changes")) {
              if (typeof onDataChange === "function") onDataChange(msg);
            }
          } catch (e) {}
        };
        setInterval(function() {
          if (ws.readyState === 1) ws.send(JSON.stringify({ topic: "phoenix", event: "heartbeat", payload: {}, ref: "hb" }));
        }, 25000);
      } catch (e) {}
    }
  };

  window.addEventListener("popstate", function() {
    const d = document.getElementById("view-detail");
    if (d && d.style.display === "block") window.FactoryNav.closeDetail();
    const m = document.getElementById("app-modal");
    if (m && m.classList.contains("open")) window.FactoryUI.closeModal();
  });

  document.addEventListener("DOMContentLoaded", async function() {
    setTimeout(function() {
      const sp = document.getElementById("splash-screen");
      if (sp) sp.classList.add("hide");
    }, 850);
    window.FactoryUI.refreshIcons();
    const existing = window.FactoryDB ? window.FactoryDB.getUserSync() : null;
    if (existing) {
      window.FactoryNav.showAppShell();
      if (typeof window.onAppReady === "function") { try { await window.onAppReady(); } catch (e) {} }
      window.FactoryNav.ensureNonBlank();
      window.FactoryEngine.startRealtime(function() {
        if (typeof window.onAppReady === "function") { try { window.onAppReady(); } catch (e) {} }
      });
    } else {
      if (window.SF_REACTOR_MODE === "GAMING" && window.FactoryDB) {
        await window.FactoryDB.login("Player_" + String(Math.floor(100 + Math.random() * 899)), "9000000000");
        window.FactoryNav.showAppShell();
        if (typeof window.onAppReady === "function") { try { await window.onAppReady(); } catch (e) {} }
        window.FactoryNav.ensureNonBlank();
        return;
      }
      const ob = document.getElementById("onboarding-screen");
      if (ob && !localStorage.getItem("sf_ob_" + (window.SF_APP_SLUG || "app"))) {
        ob.style.display = "flex";
      } else {
        window.FactoryNav.showLogin();
      }
    }
  });
})();

app_js:
try {
window.APP_TUTORIAL_HTML = `
1. Welcome to BharatHighway Legends! Start by claiming your daily fuel bonus on the Home tab.
2. Explore the garage to unlock vehicles using coins earned from races.
3. Tap on unlocked vehicles to start a race through village and town highways.
4. Create custom highway cups on the Actions tab to challenge yourself.
5. Check your race history and leaderboard standings on the Records tab.
6. Share the app with friends to earn extra coins and unlock premium features.
7. Download your driver license PDF and reset your session from the Profile tab.
8. Use the floating action button to quickly earn extra coins.
`;

window.renderTabs = async function() {
  const user = FactoryDB.getUserSync();
  if (!user) return;

  // View 1: Home
  document.querySelector('#view-1').innerHTML = `
    <div class="sf-hero-card" style="background-color: crimson; color: white;">
      <h2>${user.name}</h2>
      <p>Driver Rank: ${FactoryUI.safeNum(user.rank)}</p>
      <p>Total Coins: ${FactoryUI.safeNum(user.coins)}</p>
      <span class="badge" style="background-color: gold;">VILLAGE HIGHWAY LIVE</span>
    </div>
    <div class="sf-stat-grid" style="background-color: crimson; color: white;">
      <div>Total Races: ${FactoryUI.safeNum(user.totalRaces)}</div>
      <div>Best Score: ${FactoryUI.safeNum(user.bestScore)}</div>
    </div>
    <div class="sf-hscroll">
      ${['scooter', 'bike', 'horse', 'bus', 'truck'].map(vehicle => `
        <div class="sf-hcard" onclick="handleVehicleClick('${vehicle}')" style="background-color: ${FactoryGame.isUnlocked(vehicle, vehicle === 'scooter') ? 'emerald' : 'crimson'}; color: white;">
          <h3>${vehicle}</h3>
        </div>
      `).join('')}
    </div>
  `;

  // View 2: Actions
  document.querySelector('#view-2').innerHTML = `
    <form onsubmit="handleCreateCup(event)" style="background-color: crimson; color: white;">
      <input type="text" placeholder="Cup Name" required>
      <select required>
        <option value="scooter">Scooter</option>
        <option value="bike">Bike</option>
        <option value="horse">Horse</option>
        <option value="bus">Bus</option>
        <option value="truck">Truck</option>
      </select>
      <input type="number" placeholder="Target Coins" required>
      <button type="submit" style="background-color: gold;">Create Cup</button>
    </form>
    <div class="sf-action-tile" onclick="FactorySound.toggle()" style="background-color: crimson; color: white;">Engine Sound Toggle</div>
    <div class="sf-action-tile" onclick="FactoryPro.showProModal('Heavy Fleet VIP Pass', 'Rs. 99 / mo')" style="background-color: crimson; color: white;">Heavy Fleet VIP Pass</div>
  `;

  // View 3: Records
  const races = await FactoryDB.getItems('race');
  const transactions = await FactoryDB.getTransactions();
  document.querySelector('#view-3').innerHTML = `
    <input id="app-search-bar" oninput="window.onSearchInput(this.value)" placeholder="Search..." style="background-color: crimson; color: white;">
    <div>
      ${races.map(race => `
        <div onclick="FactoryNav.openDetail('${race.name}', '${race.details}')" style="background-color: crimson; color: white;">
          <h3>${race.name}</h3>
          <p>${race.score}</p>
        </div>
      `).join('')}
    </div>
  `;

  // View 4: Profile
  document.querySelector('#view-4').innerHTML = `
    <h2 style="background-color: crimson; color: white;">${user.name}</h2>
    <p>Email: ${user.email}</p>
    <p>Phone: ${user.phone}</p>
    <p>Points: ${FactoryUI.safeNum(user.points)}</p>
    <button onclick="FactoryEngine.openReferShare()" style="background-color: gold;">Invite Squad +25 Coins</button>
    <button onclick="FactoryEngine.openTutorial()" style="background-color: gold;">Driving Guide</button>
    <button onclick="FactoryUI.downloadPDF()" style="background-color: gold;">Download Driver License PDF</button>
    <button onclick="FactoryNav.logout()" style="background-color: gold;">Reset Session</button>
  `;
};

window.renderTabs12 = window.renderTabs;
window.renderTabs34 = window.renderTabs;

window.onFloatingAction = function() {
  FactoryUI.modal('+20 Coins Sprint', 'Complete a quick sprint to earn +20 coins!');
};

window.onSearchInput = function(q) {
  const races = FactoryDB.getItems('race').filter(race => race.name.includes(q));
  document.querySelector('#view-3').innerHTML = `
    <input id="app-search-bar" oninput="window.onSearchInput(this.value)" placeholder="Search..." style="background-color: crimson; color: white;">
    <div>
      ${races.map(race => `
        <div onclick="FactoryNav.openDetail('${race.name}', '${race.details}')" style="background-color: crimson; color: white;">
          <h3>${race.name}</h3>
          <p>${race.score}</p>
        </div>
      `).join('')}
    </div>
  `;
};

window.onTabChange = function(tabNum) {
  FactoryUI.refreshIcons();
};

window.onAppReady = async function() {
  await window.renderTabs();
  FactoryUI.refreshIcons();
};

if (window.FactoryDB && FactoryDB.getUserSync()) {
  window.onAppReady();
}

function handleVehicleClick(vehicle) {
  if (FactoryGame.isUnlocked(vehicle, vehicle === 'scooter')) {
    FactoryGame.startVillageRace(vehicle, 'crimson');
  } else {
    FactoryNav.openDetail(vehicle, `Unlock ${vehicle} for ${vehicle === 'scooter' ? 0 : vehicle === 'bike' ? 100 : vehicle === 'horse' ? 200 : vehicle === 'bus' ? 350 : 500} coins.`);
  }
}

function handleCreateCup(event) {
  event.preventDefault();
  const cupName = event.target[0].value;
  const vehicleClass = event.target[1].value;
  const targetCoins = event.target[2].value;
  FactoryDB.saveItem('race', { name: cupName, vehicleClass, targetCoins });
}
} catch (sfErr) { console.error("AppJS Error:", sfErr); if (window.FactoryNav) window.FactoryNav.ensureNonBlank(); }
